std::string bytes(const std::filesystem::path& p){std::ifstream f(p);need(bool(f),"Missing "+p.string());return {std::istreambuf_iterator<char>(f),{}};}
InputFrame input(const Json& row){InputFrame in;const int movement=row.at("movement"),held=row.at("held"),pressed=row.at("pressed");if(movement>=0){in.movement=Direction(movement);}for(std::size_t i=0;i<in.buttons.size();++i){in.buttons[i].held=held&(1<<i);in.buttons[i].pressed=pressed&(1<<i);in.buttons[i].released=row.value("released",0)&(1<<i);}return in;}
void chain(const CombatContent& c,const std::filesystem::path& prior,const std::filesystem::path& out){
 std::filesystem::create_directories(out/"slots");const auto source=bytes(prior/"slots/slot-01.json");std::ofstream(out/"slots/slot-01.json")<<source;
 G2NaturalDriver r(c,out,"public-inputs.jsonl",[](int,int hi){return hi;});r.game.configureSaveDirectory(out/"slots");finishTitleOpening(r.game);DoraRender view(r.game,c,out/"frames");r.game.returnToTitle();finishTitleOpening(r.game);
 int previousMap=0;int credits=0,victories=0,firstPeak=0,secondPeak=0,firstDamage=0;bool reset=false;std::optional<MusicPlaybackIdentity> token;std::optional<EndingScoreResult> score;std::array<bool,5> unlocked{};std::vector<int> commits;std::map<std::string,int> cues;std::set<std::uint64_t> messages;
 r.observe=[&](const PresentationEvent& e){++cues[e.id];if(e.musicPlayback){token=e.musicPlayback;}if(r.game.mapId()>=213){view.pending.push_back(e);}};
 r.afterTick=[&]{if(r.game.mapId()>=213){view.tick();if(auto ticks=view.presentation->musicTicks()){r.game.reportMusicTicks(ticks->first,ticks->second);}}if(r.game.takeFinalBossVictory()){++victories;}
  if(!r.game.hasGame()){return;}const auto& s=r.game.session();if(r.game.mapId()==209){if(!reset){firstPeak=std::max(firstPeak,s.variable(384));firstDamage=std::max(firstDamage,s.variable(89));}if(s.flag(574)&&s.variable(384)==0){reset=true;}if(reset&&!s.flag(575)){secondPeak=std::max(secondPeak,s.variable(384));}}
  if(r.game.mapId()==213&&!score){const auto in=s.endingScoreInput();score=endingScore(in);unlocked=in.unlocked;}
  if(score){for(int id=601;id<=605;++id){if(s.flag(id)&&!unlocked[id-601]){need(r.game.mapId()==214||(previousMap==214&&r.game.mapId()==215),"Unlock did not originate from214");commits.push_back(id);unlocked[id-601]=true;}}}
  if(r.game.mapId()==214&&r.game.dialogue().active()){messages.insert(r.game.dialogue().view().request);}
  previousMap=r.game.mapId();
 };
 const auto priorEvidence=Json::parse(bytes(prior/"natural-result.json"));const int ack=priorEvidence.at("audio_first_pass_tick");std::ifstream trace(prior/"public-inputs.jsonl");std::string line;
 while(std::getline(trace,line)){const auto row=Json::parse(line);need(row.at("map")== (r.game.hasGame()?r.game.mapId():0),"Recorded public path diverged at "+std::to_string(r.ticks));r.tick(input(row));if(r.game.mapId()==211&&++credits==ack){need(token&&r.game.reportMusicFirstPass(*token),"Reused verified credit callback rejected");}}
 need(victories==1&&reset&&firstPeak>=24&&secondPeak>=24&&firstDamage>=1000,"Actual two rounds/victory missing");need(score&&r.game.mapId()==215&&commits==score->unlocks&&r.game.session().variable(381)==score->rank,"Actual score/unlock/C98->215 broken");
 for(int n=0;n<200&&r.game.mode()!=ApplicationMode::Saving;++n){r.tick();}need(r.game.mode()==ApplicationMode::Saving,"Actual Clear save absent");const auto before=r.game.session().exportState();r.tick(key(InputAction::Down));r.tick(key());need(r.game.mode()==ApplicationMode::Playing,"Clear commit failed");auto disk=SaveFiles(c,out/"slots").read(2);need(disk.continuation.kind=="clear_after_file"&&disk.session.saveCount==before.saveCount+1&&disk.continuation.statisticBefore==before.variables.at(399),"Clear counters/cursor wrong");
 for(int n=0;n<400&&!r.game.inputPromptView().cursor;++n){r.tick();}need(r.game.mapId()==216&&r.game.inputPromptView().cursor,"Actual PCM return failed");view.frame("current-clear216");need(bytes(prior/"slots/slot-01.json")==source,"Original source modified");
 std::ofstream(out/"chain-result.json")<<Json{{"kind","current08 public-input replay of03 verified real G6 source, reused credit audio feedback, actual current score/Clear PCM/save"},{"runtime_state_injection",false},{"source_sha256",contentSha256(source)},{"steps",r.ticks},{"maps",r.maps},{"victories",victories},{"first_peak",firstPeak},{"second_peak",secondPeak},{"first_damage",firstDamage},{"hit_counter_reset",reset},{"rank",score->rank},{"unlocks",commits},{"unlock_requests",messages.size()},{"C98_actual215",true},{"native_before",before.saveCount},{"native_after",disk.session.saveCount},{"V399",disk.continuation.statisticBefore},{"Clear_sha256",contentSha256(bytes(out/"slots/slot-02.json"))},{"C2_count",cues["m215-e1-p1-c2"]}}.dump(2)<<'\n';std::cout<<"G7 current whole ending/score/unlock/Clear PASS steps="<<r.ticks<<'\n';
}
void independent(const CombatContent& c,const std::filesystem::path& slot,const std::filesystem::path& out){
 std::filesystem::create_directories(out/"slots");std::filesystem::copy_file(slot,out/"slots/slot-02.json",std::filesystem::copy_options::overwrite_existing);const auto disk=decodeSave(c,bytes(slot));G2NaturalDriver r(c,out);DoraRender view(r.game,c,out/"frames");r.game.configureSaveDirectory(out/"slots");finishTitleOpening(r.game);int c2=0;r.observe=[&](const PresentationEvent&e){view.pending.push_back(e);c2+=e.id=="m215-e1-p1-c2";};r.afterTick=[&]{view.tick();if(auto t=view.presentation->musicTicks()){r.game.reportMusicTicks(t->first,t->second);}};
 r.game.returnToTitle();finishTitleOpening(r.game);r.tick(key());r.tick(key(InputAction::Down));r.tick(key());need(r.game.mapId()==215,"Independent public Clear Load missing");for(int n=0;n<400&&!r.game.inputPromptView().cursor;++n){r.tick();}need(r.game.mapId()==216&&r.game.inputPromptView().cursor&&c2==0&&r.game.session().saveCount()==disk.session.saveCount&&r.game.session().variable(399)==disk.continuation.statisticBefore,"Independent Load replayed C2/counts");r.tick(key(InputAction::Cancel));for(int n=0;n<400&&r.game.mapId()!=217;++n){r.tick();}need(r.game.mapId()==217&&r.game.session().variable(635)==0,"Actual Cancel bonus failed or incremented cycle");r.settle();need(r.game.foreground()==ForegroundKind::None&&r.game.playerVisible()&&r.game.world().player().active&&r.game.world().player().opacity()==255,"Bonus entry has not released its visible HUNK");need(r.game.session().inParty(8)&&r.game.world().player().motion.tile()==TilePosition{17,23}&&r.game.world().player().spriteId==c.catalog.at("bonus").at("sprite"),"Bonus entry HUNK tail not completed");for(int n=0;n<25;++n){r.tick();}view.frame("independent-load-bonus");std::ofstream(out/"load-result.json")<<Json{{"independent_process_public_Load",true},{"C2_replayed",c2},{"native",r.game.session().saveCount()},{"V399",r.game.session().variable(399)},{"V635",r.game.session().variable(635)},{"Cancel_actual217",true},{"steps",r.ticks}}.dump(2)<<'\n';std::cout<<"G7 independent public Clear Load/counts/actual bonus PASS\n";
}
// Reuse verified public navigation traces with the current real cycle disk.
// Each stage begins through title Load and emits only legal public saves.
void cycleTrace(const CombatContent& c,const std::filesystem::path& planPath,const std::filesystem::path& out){
 const auto plan=Json::parse(bytes(planPath));std::filesystem::path source=plan.at("source").get<std::string>();Json results=Json::array();std::string rngMode;std::mt19937 random;int total=0;
 G2NaturalDriver r(c,out,"public-inputs.jsonl",[&](int lo,int hi){if(rngMode=="seed"){return std::uniform_int_distribution<int>(lo,hi)(random);}if(rngMode=="replay03"&&lo==1&&hi==2){return 1;}if(rngMode=="replay04"&&lo==0&&hi==400){return 0;}if(rngMode=="replay04"&&lo==0&&hi==10){return 6;}return safe(lo,hi);});
 SavedPresentation presentation;int fade=0;
 r.observe=[&](const PresentationEvent& e){if(e.kind==PresentationEvent::Kind::Music){presentation.music=e.sound;fade=0;}if(e.kind==PresentationEvent::Kind::StopMusic){presentation.music={};fade=0;}if(e.kind==PresentationEvent::Kind::FadeMusic){fade=(e.duration+16)/17;}if(e.kind==PresentationEvent::Kind::Cue){const auto& cue=c.cue(e.id);if(cue.at("kind")=="tint"){for(int n=0;n<3;++n){presentation.tone[n]=cue.at("tone_percent").at(n);}presentation.saturation=cue.at("tone_percent").at(3);}}};
 r.afterTick=[&]{if(fade>0&&!--fade){presentation.music={};}r.game.setPresentationState(presentation);};
 for(const auto& stage:plan.at("stages")){
  const auto raw=bytes(source);const auto before=decodeSave(c,raw);presentation=before.presentation;fade=0;need(before.session.worldValues.at(c.facts.variables.at(635))==1,"Cycle trace source is not the actual completed first cycle");
  const auto folder=out/stage.at("name").get<std::string>();std::filesystem::create_directories(folder);std::ofstream(folder/"slot-01.json")<<raw;if(stage.value("seed_slot2",false)){std::ofstream(folder/"slot-02.json")<<raw;}
  r.game.returnToTitle();finishTitleOpening(r.game);r.game.configureSaveDirectory(folder);finishTitleOpening(r.game);rngMode=stage.value("mode",std::string("replay"));random.seed(stage.value("seed",19202026u));std::ifstream trace(stage.at("trace").get<std::string>());need(bool(trace),"Missing actual public cycle stage trace");std::string line;int steps=0;bool entered=false;const int limit=stage.value("limit",0);
  while(std::getline(trace,line)&&(!limit||steps<limit)){const auto row=Json::parse(line);if(row.contains("map")){need(row.at("map")== (r.game.hasGame()?r.game.mapId():0),"Cycle trace map diverged at "+stage.at("name").get<std::string>()+" step="+std::to_string(steps)+" actual="+std::to_string(r.game.hasGame()?r.game.mapId():0));}r.tick(input(row));entered|=r.game.hasGame();need(!entered||r.game.mode()!=ApplicationMode::Title,"Cycle trace returned to Title at "+stage.at("name").get<std::string>()+" step="+std::to_string(steps));++steps;}
  need(!limit||steps==limit,"Cycle trace successful prefix is too short");source=folder/stage.at("output").get<std::string>();const auto disk=SaveFiles(c,folder).read(std::stoi(stage.at("output").get<std::string>().substr(5,2)));need(disk.scene.map==stage.value("expected_map",disk.scene.map)&&disk.session.worldValues.at(c.facts.variables.at(635))==1&&disk.session.saveCount>before.session.saveCount,"Public cycle save lost completion count or did not commit");need(bytes(folder/"slot-01.json")==raw,"Public cycle stage rewrote its isolated source disk");total+=steps;results.push_back(Json{{"stage",stage.at("name")},{"steps",steps},{"map",disk.scene.map},{"native",disk.session.saveCount},{"V635",1},{"source_sha256",contentSha256(raw)},{"output_sha256",contentSha256(bytes(source))},{"local_only_output",source.string()},{"runtime_state_injection",false}});std::ofstream(out/"cycle-trace-result.json")<<Json{{"completed_stages",results},{"total_steps",total},{"runtime_state_injection",false}}.dump(2)<<'\n';std::cout<<"Actual cycle stage "<<stage.at("name")<<" PASS map="<<disk.scene.map<<" count="<<disk.session.saveCount<<" steps="<<steps<<'\n';
 }
}

