int main(int argc,char**argv){try{std::cout.setf(std::ios::unitbuf);need(argc==5,"package output chain|load prior-dir|slot");const auto c=loadCombatContent(argv[1]);std::filesystem::create_directories(argv[2]);if(std::string(argv[3])=="chain"){chain(c,argv[4],argv[2]);}else if(std::string(argv[3])=="cycle-trace"){cycleTrace(c,argv[4],argv[2]);}else{need(std::string(argv[3])=="load","Unknown mode");independent(c,argv[4],argv[2]);}return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
